import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"NORA: A Small Open-Sourced Generalist Vision Language Action Model for Embodied Tasks","description":"","frontmatter":{"title":"NORA: A Small Open-Sourced Generalist Vision Language Action Model for Embodied Tasks","arxiv":"2504.19854","date":"2025-04-28","authors":"Chia-Yu Hung, Qi Sun, Pengfei Hong, Amir Zadeh, Chuan Li, U-Xuan Tan, Navonil Majumder, Soujanya Poria","categories":"cs.RO, cs.AI, cs.CV","topics":"VLA 模型, 动作 tokenization, 轻量化部署","outline":[2,2]},"headers":[],"relativePath":"papers/2504.19854.md","filePath":"papers/2504.19854.md","lastUpdated":null}'),e={name:"papers/2504.19854.md"};function l(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="nora-a-small-open-sourced-generalist-vision-language-action-model-for-embodied-tasks" tabindex="-1">NORA: A Small Open-Sourced Generalist Vision Language Action Model for Embodied Tasks <a class="header-anchor" href="#nora-a-small-open-sourced-generalist-vision-language-action-model-for-embodied-tasks" aria-label="Permalink to &quot;NORA: A Small Open-Sourced Generalist Vision Language Action Model for Embodied Tasks&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2504.19854" target="_blank" rel="noreferrer">2504.19854</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-04-28</td></tr><tr><td><strong>作者</strong></td><td>Chia-Yu Hung, Qi Sun, Pengfei Hong, Amir Zadeh, Chuan Li, U-Xuan Tan, Navonil Majumder, Soujanya Poria</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 Qwen-2.5-VL-3B 当骨干、FAST+ 做动作 tokenizer，在 97 万条 OXE 轨迹上训一个 3B 的 VLA，用不到 OpenVLA 一半的参数在真机 WidowX 上打赢它。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>现有 VLA 的参数量普遍逼近甚至超过 7B（OpenVLA 7B，TraceVLA、ECOT、EMMA-X 更大），推理时的显存与延迟让它们很难跑在实时机器人回路里；更现实的问题是，大部分使用者拿到 VLA 后要做的第一件事是<strong>在自己的任务上 fine-tune</strong>，而 7B 模型的微调基本排除了消费级 GPU。论文明确把「需要一个能在消费级 GPU 上微调的小模型」写进了动机。</p><p>第二个问题更技术：作者观察到现有 VLA 的失败常常来自<strong>视觉编码的局限</strong>，典型表现是抓取时抓不准位置。这不是语言理解的问题，而是空间定位（grounding）的问题。把这两条合起来，论文要回答的是：把骨干换成一个视觉定位能力更强的小 VLM，再配一个高效的动作 tokenizer，能不能在参数量减半的同时把真机成功率提上去。这件事的价值在于，它检验了 VLA 的性能瓶颈到底是「模型容量」还是「骨干的视觉-空间能力」。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>RT-1 [Brohan 2023c] 证明了大规模机器人演示可以训出跨任务的行为策略，Octo 用组合式框架支持多任务控制，两者共同确立了「数据多样性 + 模块化架构」的路线。RT-2 [Brohan 2023a] 把互联网视觉-语言数据与机器人轨迹混训，RT-2-X 进一步把模型放大到 55B 并在 Open X-Embodiment 上训练。OpenVLA [Kim 2024] 的贡献是开放性：7B 参数、97 万条真实演示、DINOv2 + SigLIP 的视觉编码器 + Llama 2，让整个社区能复现。</p><p>不足在几个不同层面。<strong>算力层面</strong>：这些模型即便性能好，7B 起步的规模让实时控制与本地微调都不现实；引入 CoT 的方法（ECOT、TraceVLA、EMMA-X）虽然提升了推理能力，但需要在执行时处理中间推理步骤，开销进一步放大。<strong>视觉层面</strong>：OpenVLA 把动作 token 塞进 LLaMA tokenizer 里最不常用的 256 个 token，动作离散化用的是每维分箱，这既没有利用动作维度之间的相关性，也没有改善视觉定位。<strong>空间先验层面</strong>：SpatialVLA [Qu 2025] 试图用 Ego3D 位置编码与自适应动作栅格显式注入 3D 信息，但作者在实验中发现，它虽然能正确判断空间方位，抓取本身却经常失败——空间理解正确不等于操作成功。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>在这篇论文出现之前，几件事已经成立。第一，VLA 的能力很大程度上继承自 VLM 骨干的预训练；如果骨干的物体定位与空间关系理解更强，动作 grounding 理应更好。第二，Qwen2.5-VL 的一个显著设计是训练时使用原生图像分辨率，官方技术报告把它与更准确的物体尺寸/位置理解、更好的检测与定位性能联系起来。第三，FAST [Pertsch 2025] 提出对动作序列先做 DCT 去相关、再用 BPE 压缩，把动作序列变成对语言模型友好的短 token 串，已经在单臂、双臂、移动机器人上验证过。</p><p>于是一条推理链自然成型：如果 VLA 的抓取失败主要来自视觉定位，而不是模型容量，那么<strong>换一个定位更强的 3B 骨干 + 一个更高效的动作 tokenizer，就有可能在参数减半的情况下超过 7B 基线</strong>。这条推理不需要任何新的架构发明，它的价值恰恰在于把「性能来自哪里」这个问题变成可检验的实验。作者甚至在 intro 里点明：他们想验证不需要动作栅格或空间嵌入，也能超过 SpatialVLA。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>VLA 的抓取失败常被误读为「模型太小、推理不够」，但更可能是骨干的视觉定位不准。换一个原生分辨率训练、空间 grounding 更强的小 VLM，再用 DCT + BPE 把动作压成短 token 串减轻自回归负担，3B 就够了。剩下的性能差距不是靠加参数补上的，而是靠 action chunking 补上的——而 chunking 的收益又强烈依赖控制频率。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>模型 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">M</span></span></span></span> 是一个预训练 VLM，输入为单帧视觉观测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与语言指令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span>，拼成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">c</span><span class="mclose">]</span></span></span></span>，自回归地预测一段离散 token <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">]</span></span></span></span>，再解码成动作块：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">c</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">←</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord text"><span class="mord">FAST+</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">decode</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></span></p><p>具体配置：骨干选 Qwen-2.5-VL-3B；tokenizer 词表额外扩充 2048 个 FAST+ token；观测保持单帧无历史；NORA 的 action chunk size 为 1，训练目标就是标准的 next-token prediction。预训练数据是 Open X-Embodiment（含 BridgeV2、DROID 等子集），沿用 OpenVLA 的做法把所有帧 resize 到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">224</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">224</span></span></span></span>。训练规模是单节点 8×H100 跑约三周、合计约 4000 H100 GPU 小时，batch size 256，110 万次梯度更新，AdamW，前 5 万步线性 warmup 到峰值学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span> 后余弦衰减到 0，FlashAttention + bf16。推理时约占 8.3 GB 显存。</p><p>作者另外训了一个变体 NORA-Long：架构完全相同，但 chunk size 为 5，即一次预测未来 5 步动作，在同样的数据上预训练 90 万步。</p><p>下游用法以 LIBERO 为例：在 LIBERO 训练集上微调 150 epoch，batch size 128，学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>；策略输入第三人称相机画面与自然语言指令，输出末端速度动作。真机侧是 WidowX-250 平台，9 个任务，每任务 10 次试验，成功记 1、失败记 0。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化很轻，核心只有离散 token VLA 的模仿学习目标与 FAST+ 的动作压缩思想。</p><p>策略被写成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，即给定图像 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、文本指令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与先前状态上下文 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，预测一串可执行的离散 token <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，训练即最小化对专家动作 token 序列的 next-token 交叉熵。</p><p>真正值得展开的是动作 tokenization 的 intuition。传统做法（RT-1/RT-2/OpenVLA）对每个动作维度独立做分位数分箱，映射到 256 个离散 bin。问题是相邻时刻的动作高度相关、各维度之间也相关，逐维逐时刻离散化会产生大量冗余 token，序列长、收敛慢。FAST 的做法是先沿动作维度做离散余弦变换（DCT），把时间上平滑的信号集中到少数低频系数上，从而<strong>去相关</strong>；再对量化后的系数跑 BPE 压缩成更短的 token 串。结果是词表更小、序列更短、token 统计更接近语言数据，收敛更快。评估指标很朴素：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord cjk_fallback">成功率</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">100</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span><span class="mrel mtight">∼</span><span class="mord mtight"><span class="mord mathcal mtight" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:-0.0278em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">eval</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1512em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2559em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord">1</span><span class="mopen">[</span><span class="mord text"><span class="mord cjk_fallback">任务</span><span class="mord"> </span></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mord text"><span class="mord"> </span><span class="mord cjk_fallback">成功完成</span></span><span class="mclose">]</span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mord">%</span></span></span></span></span></p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：小骨干能否在真机上超过大模型？</strong> 在 WidowX-250 的 9 个任务上对比 RT-1、OpenVLA、SpatialVLA。NORA 平均成功率 56.7%，OpenVLA 40%，SpatialVLA 11.1%，RT-1 4.4%。分类看，OOD 物体抓取上 NORA 表现最强（&quot;put carrot in pot&quot; 与 &quot;put banana in pot&quot; 均为 90%）；空间推理任务上总体占优（&quot;move the banana close to the pan&quot; 80%）；多物体任务上虽仍领先，但优势明显收窄且绝对值低（三个多物体任务分别为 40%、30%、30%），作者自己承认这里仍有很大改进空间。SpatialVLA 的失败模式很具体：它能判断对方位，但 affordance 点估计错误导致抓不起来。</p><p><strong>问题二：能否适配新的 embodiment？</strong> 在 LIBERO 四个套件、每方法 500 次试验上评测。OpenVLA 微调平均 76.5%，TraceVLA 74.8%，NORA 微调 73.9%（在 LIBERO-Long 上只有 45，明显落后）；加上 action chunking 后 NORA-fine-tuned-AC 平均 79.5%，超过 SpatialVLA-AC 的 78.1%；而预训练阶段就带 chunking 的 NORA-Long 微调后达到 87.9%，四个套件全面领先，LIBERO-Long 达到 74.6%。结论是 chunking 对长时序任务是关键，而在预训练阶段就学 chunking 比在微调阶段才加更有效。</p><p><strong>问题三：chunking 在真机上也成立吗？</strong> 不成立。这是全文最有价值的负结果。把 NORA-Long 预测的 5 个动作全部顺序执行时，WidowX 频繁撞进环境，因为累积动作幅度过大；SpatialVLA 一次执行 4 个动作时也有同样的撞击行为。改成只执行每个 chunk 的第一个动作后，&quot;put carrot in the pot&quot; 达到 80%，空间任务 &quot;put the pink toy at the right corner&quot; 达 70%（与 NORA 相当），但多物体 pick-and-place 直接归零——NORA-Long 放完第一个物体后就不动了。作者还观察到 NORA-Long 倾向从侧面（约 2 点钟方向）抓取，NORA 倾向从正上方抓取，前者对小物体（香蕉）非常不利，导致 &quot;move the banana close to the pan&quot; 只有 40%。作者给出的解释假说是：chunking 在高控制频率下才有效（Diffusion Policy 插值到 125 Hz、OpenVLA-OFT+ 在 25 Hz 的 ALOHA 上有效、LIBERO 为 20 Hz），而他们手头的 WidowX 平台不支持高频控制。</p><p><strong>问题四：抗干扰能力如何？</strong> 选三个 OpenVLA 与 NORA 都表现良好的任务，往场景里加干扰物。两个策略都出现显著性能下降，作者直言这暴露了两者的脆弱性——这不是 NORA 独有的优势，而是共同的短板。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：NORA 用 Qwen-2.5-VL-3B 替换 7B 骨干、用 FAST+ 替换逐维分箱，在 97 万条 OXE 演示上训了约 4000 H100 小时。真机 WidowX 上平均成功率 56.7%，超过 OpenVLA 的 40% 与 SpatialVLA 的 11.1%，推理仅需约 8.3 GB 显存。LIBERO 上普通版微调不敌 OpenVLA（73.9 vs 76.5），但预训练即带 chunk size 5 的 NORA-Long 达到 87.9%。真机实验给出了一个明确的负结果：action chunking 在 20 Hz 的 LIBERO 上大幅提升长时序表现，在低频的 WidowX 上却导致撞击、多物体任务归零、affordance 估计变差。加入干扰物后 NORA 与 OpenVLA 都显著退化。</p><p><strong>3 句话版</strong>：VLA 的抓取失败更多来自骨干的视觉定位而非参数量，换个定位更强的 3B 骨干就能超过 7B 基线。Action chunking 的收益强依赖控制频率，仿真上的增益不能直接外推到真机。两者都对场景干扰物脆弱。</p><p><strong>1 句话版</strong>：把 VLA 的性能来源从「参数规模」重新归因到「骨干视觉定位 + 动作 tokenization」，并附上一个 chunking 不可跨频率外推的反例。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是<strong>归因假设</strong>：NORA 相对 OpenVLA 的真机优势来自 Qwen-2.5-VL-3B 更强的视觉-语义定位能力。这条假设一旦不成立，论文的核心 claim（小模型靠更好的骨干就能赢）就退化为一次幸运的工程组合。</p><p>它在实践中可能不成立，因为 NORA 相对 OpenVLA 同时改了三件事：骨干（Qwen2.5-VL vs DINOv2+SigLIP+Llama2）、动作 tokenizer（FAST+ vs 逐维分箱）、以及训练配方（4000 H100 小时、110 万步更新、特定的 warmup/衰减）。论文提供的证据是消融式的动作预测策略比较（单步 vs chunk）与 SpatialVLA 的定性失败分析，但<strong>没有做骨干与 tokenizer 的解耦消融</strong>——例如「Qwen2.5-VL-3B + 逐维分箱」或「OpenVLA 骨干 + FAST+」。缺这两组对照，就无法排除「增益主要来自 FAST+ 带来的更快收敛与更短序列」这个替代解释。此外真机每任务仅 10 次试验，40% 与 56.7% 这类差距在这个样本量下的置信区间相当宽，这一点论文没有讨论。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内、不复现整套预训练的最小验证，目标是拆开「骨干」与「tokenizer」的贡献。</p><ul><li>数据：只取 BridgeV2 的一个子集（几万条轨迹足够），或直接用 LIBERO 训练集，避免 OXE 全量预训练。</li><li>实现：训四个变体，均从公开 VLM 权重出发做同等步数的微调——(a) Qwen2.5-VL-3B + FAST+，(b) Qwen2.5-VL-3B + 256-bin 逐维分箱，(c) 另一个同规模但非原生分辨率训练的 3B VLM + FAST+，(d) 同一 3B VLM + 分箱。</li><li>测量：LIBERO-Spatial 与 LIBERO-Object 的成功率、达到同一训练损失所需步数、平均动作 token 序列长度。</li><li>判定：若 (a)−(c) 的差距（换骨干）显著大于 (a)−(b) 的差距（换 tokenizer），支持论文的骨干归因；若反过来，则说明主要增益来自 FAST+ 的序列压缩与收敛加速，论文关于「视觉定位是瓶颈」的叙述需要修正。这个实验不需要真机，因为它检验的是归因而非绝对性能。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击针对 chunking 结论的可外推性，并给出一个替代解释。论文把 NORA-Long 在真机上的失败归因于「控制频率不够高」，但同样能解释全部观测的另一个假说是：<strong>预训练时的 chunk size 改变了模型学到的 affordance 分布</strong>。作者自己报告了关键证据——NORA-Long 一致地从侧面（2 点钟方向）抓取，NORA 从上方抓取，这是策略先验的差异，与控制频率无关。</p><p>设计一个能区分两个假说的实验：在同一台 WidowX 上，人为把 NORA（chunk size 1）的控制回路降频到与 NORA-Long 实际执行时相同的等效频率，再比较两者的抓取入射角分布与小物体成功率。若降频后的 NORA 仍从上方抓取且小物体成功率不掉，则频率假说被证伪，真正原因是 chunk 预训练改变了 affordance 先验——这会把论文「chunking 需要高频」的建议改写成「chunking 会改变抓取策略，需要针对目标物体尺寸重新评估」。</p><p>另一类可预测的失败场景：多物体顺序任务上 NORA-Long 归零，是因为它「放完第一个物体就停止」。这暗示 chunk 训练让模型把「任务完成」的判断绑定到了 chunk 边界。任何需要在一条指令内完成两个以上原子动作的场景，都可能复现这个失败，而这与控制频率无关。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：论文把 chunk size 当作一个训练前就要定死的超参数，然后发现它在仿真（20 Hz）与真机（低频）上的最优值相反。这暴露了一个更本质的问题——动作 token 序列的时间粒度被硬编码进了模型，而实际部署的控制带宽是运行时才知道的。</p><p><strong>新的 framing</strong>：把 chunk size 从超参数变成<strong>推理时可调的解码变量</strong>。既然 FAST+ 已经用 DCT 把动作序列投影到频域，那么&quot;预测多长的未来&quot;在频域里等价于&quot;保留多少低频系数&quot;。可以训练单一模型输出可变长度的频域系数串，部署时根据实测控制频率与执行延迟，在线决定截断到第几阶——高频平台多取几阶、低频平台少取几阶，无需重新训练两个模型。</p><p><strong>可借鉴的相邻领域工具</strong>：这与语音/视频编码中的可伸缩码流（scalable bitstream）以及扩散模型的可变步数采样是同一类思想——一次编码，按信道条件解码到不同保真度。训练侧可以借鉴嵌套式表示学习（Matryoshka 式的多粒度监督），让前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 阶系数本身就构成一个可用的动作块。</p><p><strong>第一个实验</strong>：在 LIBERO 上训一个带多粒度损失的 NORA 变体（同时监督截断到 1、2、5 阶的重建动作），然后在<strong>同一个 checkpoint</strong> 上分别以等效 20 Hz 与人为降频两档评测，比较它与固定 chunk size 1 / 5 两个专用模型的表现。若单模型在两个频率下都不劣于对应的专用模型，就证明时间粒度确实可以延后到推理时决定，也就消除了本文最尴尬的那个仿真-真机结论倒挂。</p>',49)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
